insert into promo_rules (slug, title, content, keywords, sort_order) values
  ('aviso', 'Aviso', 'Promoção "Tumelero 60 Anos — Ninguém facilita tanto". Regulamento provisório, sujeito a autorização da SPA/MF.', array['regulamento', 'autorização', 'oficial', 'provisório', 'spa']::text[], 0),
  ('premio', 'Prêmio', '1 (um) Fiat Strada 0 km sorteado por mês, durante os 12 meses da promoção.', array['prêmio', 'carro', 'strada', 'fiat', 'ganhar', 'sorteia', 'quantos']::text[], 1),
  ('como-participar', 'Como participar', 'A cada R$ 300,00 em compras (loja física ou site), o cliente ganha 1 cupom para o sorteio do mês.', array['participar', 'cupom', 'cupons', '300', 'compra', 'site', 'loja', 'como']::text[], 2),
  ('dia-t', 'Dia T', 'Produtos da "Oferta do Dia T" contam em dobro. Fórmula: cupons = floor((valor_normal + 2 × valor_dia_T) / 300). Exemplo: compra de R$ 950, sendo R$ 300 em Ofertas do Dia T → (650 + 600) / 300 = 4 cupons.', array['dia t', 'dobro', 'oferta', 'fórmula', 'conta', 'calcular']::text[], 3),
  ('cadastro', 'Cadastro', 'CPF + número da nota fiscal, pelo site ou pelo WhatsApp com o João.', array['cadastro', 'cadastrar', 'nota', 'nf', 'cpf', 'registrar', 'whatsapp']::text[], 4),
  ('soma-por-nota', 'Soma por nota fiscal', 'Os valores são somados por nota fiscal. O saldo que sobra não acumula para outra compra.', array['saldo', 'sobra', 'acumula', 'somar', 'juntar', 'notas']::text[], 5),
  ('validade', 'Validade dos cupons', 'Os cupons valem para o sorteio do mês da compra.', array['validade', 'vale', 'mês', 'próximo', 'valem']::text[], 6),
  ('sorteio', 'Sorteio', 'Mensal, pela extração da Loteria Federal do último sábado do mês.', array['sorteio', 'quando', 'data', 'loteria', 'federal', 'sábado', 'resultado']::text[], 7),
  ('quem-participa', 'Quem pode participar', 'Pessoas físicas maiores de 18 anos com CPF válido. Funcionários Tumelero e familiares diretos não participam.', array['quem', 'idade', '18', 'funcionário', 'cnpj', 'empresa', 'menor', 'família', 'pode']::text[], 8),
  ('ganhador', 'Ganhador', 'Contato por telefone e WhatsApp em até 5 dias úteis; entrega do veículo em até 30 dias.', array['ganhador', 'ganhei', 'contato', 'entrega', 'aviso', 'receber']::text[], 9),
  ('nao-participam', 'O que não participa', 'Não participam: serviços, frete e gift cards.', array['frete', 'serviço', 'gift', 'card', 'vale-presente', 'não participa', 'conta']::text[], 10);
